update pages set contenu = '{"sections":[]}'::jsonb where path = '/bureau-etudes/bureau-etude-electronique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Bureau d''étude électronique : une carte pensée pour être réparée","mecanisme":"Notre bureau d''étude électronique est adossé à des techniciens qui dépannent de l''électronique industrielle toute l''année. Une carte sort d''ici avec ses points de mesure, sa documentation et ses composants trouvables. C''est une branche de notre [bureau d''étude mécanique](/bureau-etudes/).","cta":"Faire chiffrer mon étude électronique","telephone":"04 78 33 72 05","phraseDelai":", du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 quand un équipement est immobilisé"},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs · techniciens et ingénieurs salariés Migen, pas de chaîne d''intermédiaires."},{"valeur":"+ 120","libelle":"clients industriels · dont plus de 80 qui reviennent chaque année."},{"valeur":"4","libelle":"agences · Lyon (siège), Montréal, Dubaï, Madrid, et des hubs techniques en France."},{"valeur":"10 %","libelle":"des candidats retenus · entretien technique et entretien comportemental, résultats partagés avec vous."}]},{"type":"probleme","punchline":"Une carte électronique en fin de vie arrête une machine qui, elle, va très bien.","puces":[{"accroche":"Le composant n''existe plus.","texte":"Le fabricant a arrêté la référence, et toute la machine dépend d''une pièce introuvable."},{"accroche":"La carte de rechange coûte le prix d''un sous-ensemble neuf.","texte":"Quand elle est encore au catalogue."},{"accroche":"Personne n''a le schéma.","texte":"La documentation est partie avec le constructeur, ou n''a jamais été remise."},{"accroche":"Le diagnostic tourne en rond.","texte":"Un défaut intermittent sur une carte non documentée immobilise la ligne plusieurs jours."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Cadrage et cahier des charges électronique","texte":"fonctions attendues, contraintes d''environnement, alimentations, interfaces avec l''existant"},"benefice":"Le besoin est écrit avant d''être dessiné. Vous pouvez consulter ailleurs avec le même document"},{"prestation":{"accroche":"Conception électronique","texte":"schéma, choix des composants, définition des entrées et sorties, implantation dans le coffret"},"benefice":"Les composants retenus sont disponibles et sourçables, pas des références rares qui vous piègent dans trois ans"},{"prestation":{"accroche":"Conception de carte électronique","texte":"dossier de fabrication, nomenclature, spécifications, documentation de test"},"benefice":"Vous êtes propriétaire du dossier. Vous pouvez faire refabriquer la carte quand vous voulez, chez qui vous voulez"},{"prestation":{"accroche":"Réalisation confiée à un atelier partenaire","texte":", suivi et réception des cartes"},"benefice":"Nous ne vendons pas de cartes, donc rien ne nous pousse à en faire fabriquer plus que nécessaire. Aucune marge sur les pièces"},{"prestation":{"accroche":"Intégration et mise en service","texte":"sur la machine par nos techniciens"},"benefice":"Celui qui a dessiné la carte n''est pas parti quand elle arrive sur site. Les écarts se règlent tout de suite"},{"prestation":{"accroche":"Traitement de l''obsolescence","texte":"reprise d''une fonction existante quand la carte d''origine n''est plus fournie"},"benefice":"La machine repart sans être remplacée. L''investissement porte sur la fonction, pas sur l''équipement entier"}],"prose":[{"texte":"Nos techniciens interviennent sur l''électronique de commande des machines en exploitation, indépendamment de toute étude."}]}]'::jsonb) where path = '/bureau-etudes/bureau-etude-electronique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"Votre appel ou votre formulaire.","texte":"Rappel dans l''heure par un interlocuteur technique. Marque, référence, symptôme, criticité de la machine."},{"titre":"État des lieux.","texte":"Ce qui existe, ce qui est documenté, ce qui ne l''est plus. Une carte sans schéma se relève : c''est un travail à part entière, et il est chiffré."},{"titre":"Arbitrage.","texte":"Réparer, reconcevoir, ou remplacer par un standard du marché. Trois chiffres en face de trois options, vous décidez."},{"titre":"Conception.","texte":"Schéma, choix des composants, implantation, dossier de fabrication et documentation de test."},{"titre":"Réalisation.","texte":"Fabrication chez l''atelier partenaire, réception des cartes, contrôle avant montage."},{"titre":"Intégration et mise en service.","texte":"Montage sur la machine par nos techniciens, essais en conditions réelles, remise du dossier."},{"titre":"Suite d''exploitation.","texte":"Les mêmes équipes peuvent assurer ensuite le préventif et le curatif. Voir [maintenance corrective](/expertises/types-de-maintenance/maintenance-corrective/)."}]},{"type":"garanties","puces":[{"accroche":"Un rappel dans l''heure","texte":"du lundi au vendredi, 8h00 à 18h30, au 04 78 33 72 05, et une astreinte 24/24 et 7/7 quand la machine est à l''arrêt."},{"accroche":"Le dossier est à vous.","texte":"Schémas, nomenclatures, documentation de test : vous repartez avec de quoi faire refabriquer ailleurs. Nous ne gardons pas votre machine en otage."},{"accroche":"Des compétences évaluées","texte":"entretien technique et comportemental à l''entrée, 10 % des candidats retenus, résultats partagés avec vous."}]},{"type":"cta","question":"Besoin de savoir si votre carte se répare, se refait ou se remplace ?","bouton":"Faire chiffrer mon étude électronique","href":"/contact/","rappel":"04 78 33 72 05, rappel dans l''heure"},{"type":"preuves","preuves":[{"titre":"[Étude de cas TIMESCOPE : casques de réalité virtuelle](/preuves/timescope/) · Depuis février 2024. Maintenance sous contrat d''un parc d''équipements électroniques déployé partout en France, étanchéité et réglages traités comme des sujets à part entière, propositions d''amélioration de la fiabilité."},{"titre":"[Étude de cas MERSEN : nouvelles lignes](/preuves/mersen/) · 2025, près de Lyon. Un automaticien SIEMENS sur site pour le démarrage d''une ligne neuve, quand la partie commande décide du calendrier."},{"titre":"[Étude de cas JOINT LYONNAIS : défaillances machines](/preuves/joint-lyonnais/) · Lyon, depuis février 2024. Diagnostic sur site et plusieurs solutions chiffrées, plutôt qu''un rachat de matériel."},{"titre":"[Étude de cas EATON : mise en production](/preuves/eaton-mise-en-production/) · Janvier 2023. Six techniciens multidisciplinaires pour l''installation et la mise en production d''un parc machines neuf."}]}]'::jsonb) where path = '/bureau-etudes/bureau-etude-electronique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Fabriquez-vous les cartes vous-mêmes ?","reponse":"Non. Nous concevons, nous rédigeons le dossier, nous suivons la fabrication chez un atelier partenaire et nous réceptionnons. Ne pas fabriquer est ce qui rend notre arbitrage crédible : nous n''avons rien à écouler."},{"question":"Pouvez-vous travailler sans le schéma d''origine ?","reponse":"Oui, c''est le cas le plus fréquent. Le relevé de la carte existante est une prestation à part entière, chiffrée avant d''être lancée. Vous savez ce que ça coûte avant de vous engager."},{"question":"Une réparation de carte électronique industrielle vaut-elle mieux qu''un remplacement ?","reponse":"Cela dépend de trois choses : la disponibilité du composant fautif, la criticité de la machine et ce que coûte un nouvel arrêt. Nous posons les options chiffrées, vous tranchez. Nous n''en poussons aucune."},{"question":"Qui intervient réellement sur mon matériel ?","reponse":"Des techniciens et des ingénieurs salariés Migen, évalués en entretien technique et comportemental : 10 % des candidats retenus. Ils sont habilités selon les exigences de votre site et accueillis à votre protocole de sécurité."},{"question":"Reprenez-vous un dossier commencé par un autre prestataire ?","reponse":"Oui. Nous repartons de vos fichiers, nous vérifions les hypothèses, nous chiffrons uniquement le reste à faire. Aucune obligation de tout recommencer."},{"question":"Intervenez-vous partout en France ?","reponse":"Oui. Quatre agences, Lyon (siège), Montréal, Dubaï, Madrid, et des hubs de techniciens dans les grandes villes de France. Le siège du groupe est à Limonest, près de Lyon."}]},{"type":"ctaFinal","question":"Besoin d''une électronique qui ne vous piège pas dans dix ans ?","bouton":"Faire chiffrer mon étude électronique","href":"/contact/","rappel":"04 78 33 72 05"}]'::jsonb) where path = '/bureau-etudes/bureau-etude-electronique/';
